import boto3

# Set up the Amazon Comprehend client
comprehend = boto3.client('comprehend', region_name='us-east-1')

def detect_unsafe_content(text):
    """Detect unsafe content in the given text using Amazon Comprehend."""
    try:
        response = comprehend.detect_sentiment(
            Text=text,
            LanguageCode='en'
        )
        sentiment = response['Sentiment']
        if sentiment == 'NEGATIVE':
            return True
        else:
            return False
    except Exception as e:
        print(f"Error detecting unsafe content: {e}")
        return False

import boto3

def redact_unsafe_spans(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    if response['Sentiment'] == 'NEGATIVE':
        return '[REDACTED]'
    else:
        return text

import os
from googleapiclient.discovery import build

def moderate_text(text):
    api_key = os.getenv('PERSPECTIVE_API_KEY')
    client = build('commentanalyzer', 'v1alpha1', developerKey=api_key)

    analyze_request = {
        'comment': {'text': text},
        'requestedAttributes': {'TOXICITY': {}}
    }

    response = client.comments().analyze(body=analyze_request).execute()

    toxicity_score = response['attributeScores']['TOXICITY']['summaryScore']['value']
    return toxicity_score

if __name__ == '__main__':
    user_text = 'Sample text to moderate.'
    score = moderate_text(user_text)
    print(f'Toxicity score: {score}')
